 {"id": "PEDS-C37-069", "sec": "HUS", "page": 168, "q": "Severe HUS may require —", "opts": ["Thymectomy", "Dialysis", "Phototherapy", "Exchange transfusion in every case"], "ans": 1, "exp": "Dialysis. (Book p168)", "type": "mcq"},
